-- Execute em db_devrent. Para InfinityFree, selecione o banco no phpMyAdmin antes de importar.
CREATE TABLE IF NOT EXISTS usuarios(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,tipo ENUM('usuario','administrador') NOT NULL DEFAULT 'usuario',ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categorias(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL UNIQUE,descricao VARCHAR(255),criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS equipamentos(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patrimonio INT UNSIGNED NOT NULL UNIQUE,nome VARCHAR(100) NOT NULL,descricao TEXT,categoria_id INT UNSIGNED NOT NULL,status ENUM('disponivel','reservado','manutencao','inativo') NOT NULL DEFAULT 'disponivel',criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_eq_cat FOREIGN KEY(categoria_id) REFERENCES categorias(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reservas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,equipamento_id INT UNSIGNED NOT NULL,tipo_equipamento VARCHAR(100) NOT NULL,descricao_colaborador TEXT,data_retirada DATE NOT NULL,patrimonio_item INT NOT NULL,status ENUM('pendente','aprovada','retirada','devolvida','cancelada') NOT NULL DEFAULT 'pendente',criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_res_user FOREIGN KEY(usuario_id) REFERENCES usuarios(id),CONSTRAINT fk_res_eq FOREIGN KEY(equipamento_id) REFERENCES equipamentos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS historico_reservas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reserva_id INT UNSIGNED NOT NULL,usuario_id INT UNSIGNED NOT NULL,acao ENUM('criada','editada','aprovada','cancelada','retirada','devolvida') NOT NULL,observacao TEXT,criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_hist_res FOREIGN KEY(reserva_id) REFERENCES reservas(id),CONSTRAINT fk_hist_user FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
